sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_AiToolGetStakeholder(vBusinessProcess,vUser,vExpected)
	{
		function TestCase_AiToolGetStakeholder_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected == false)
			{
				if (x_snc_devtools.GetValue(vResult,'message') == 'The Business Process could not be found.')
				{
					return true;
				}
				if (x_snc_devtools.GetValue(vResult,'message') == 'Could not load the user record.')
				{
					return true;
				}
				if (x_snc_devtools.GetValue(vResult,'message') == 'The user is not a stakeholder of the given Business Process.')
				{
					return true;
				}
				return false;
			}
			if (x_snc_devtools.IsObject(vResult) == false)
			{
				return false;
			}
			if (x_snc_devtools.GetStringValue(x_snc_devtools.GetValue(vResult,'message')) != '')
			{
				return false;
			}			
			if (x_snc_devtools.GetStringValue(x_snc_devtools.GetValue(vResult,'name')) == '')
			{
				return false;
			}
			return true;
		}
		
		test.TestCase(
			'Function AiToolGetStakeholder()',
			AiToolGetStakeholder,
			{
				'vBusinessProcess': vBusinessProcess,
				'vUser': vUser
			},
			vExpected,
			TestCase_AiToolGetStakeholder_CheckResult);
	}
		
	TestCase_AiToolGetStakeholder(null,null,false);


	var grBusinessProcess = new GlideRecord('x_Snc_agenticbpc_business_process');
	grBusinessProcess.initialize();
	grBusinessProcess.name = 'ATF Business Process 1';
	var strBusinessProcessSysId = grBusinessProcess.insert();

	var strUserSysId = x_snc_devtools.CreateTestUser('ATF Agentic BPC 1');

	var grStakeholder = new GlideRecord('x_snc_agenticbpc_stakeholder');
	grStakeholder.initialize();
	grStakeholder.user = strUserSysId;
	grStakeholder.business_process = strBusinessProcessSysId;
	var strStakeholderSysId = grStakeholder.insert();

	TestCase_AiToolGetStakeholder(strBusinessProcessSysId,strUserSysId,true);

	TestCase_AiToolGetStakeholder(grBusinessProcess.number,strUserSysId,true);
	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
